function DEBRUIJN(b, n):
    a <- array of zeros, length b*n
    seq <- empty list
    function DB(t, p):
        if t > n:
            if n mod p == 0:
                append a[1..p] to seq
        else:
            a[t] <- a[t-p]
            DB(t+1, p)
            for j in (a[t-p]+1) .. (b-1):
                a[t] <- j
                DB(t+1, t)
    DB(1, 1)
    return seq            # length exactly b^n  (isDeBruijn_length)

function WINDOW(seq, n, i):
    N <- length(seq)
    return ( seq[(i+t) mod N]  for t in 0..n-1 )

function CATALOG(b, n):
    seq <- DEBRUIJN(b, n)
    assert length(seq) == b^n
    table <- empty map
    for i in 0 .. b^n - 1:
        table[ WINDOW(seq, n, i) ] <- i   # window^{-1}, a bijection
    return table

